func runTuning(ctx context.Context, errW io.Writer, runners []tuneRunner, prompt, debugDir string) (changes []tunedRunner, skipped int, err error) {
	// Reuse the summary-provider resolution (selection + persistence), but pull
	// the raw TextGenerator rather than provider.Generator: the latter is a
	// summarize.Generator that turns a transcript Input into a checkpoint
	// Summary, whereas we need plain prompt->text generation here.
	provider, err := resolveCheckpointSummaryProvider(ctx, errW)
	if err != nil {
		return nil, 0, err
	}
	ag, err := agent.Get(provider.Name)
	if err != nil {
		return nil, 0, fmt.Errorf("loading provider %s: %w", provider.Name, err)
	}
	textGen, ok := agent.AsTextGenerator(ag)
	if !ok {
		return nil, 0, fmt.Errorf("provider %s cannot generate text", provider.Name)
	}

	stop := startSpinner(errW, fmt.Sprintf("Tuning %d runner(s) with %s", len(runners), provider.DisplayName))
	out, err := textGen.GenerateText(ctx, prompt, provider.Model)
	stop(err == nil)
	if err != nil {
=== dispatch.go precedent ===
				opts, err = prepareLocalDispatch(cmd.Context(), opts)
				if err != nil {
					return err
				}
				provider, err := resolveDispatchProvider(cmd.Context(), cmd.ErrOrStderr(), agentOverride)
				if err != nil {
					return err
				}
				opts.TextGenerator = provider.TextGenerator
				opts.Model = provider.Model
			}

